details.command:
kubectl get deployment app -n default --output-columns=REPLICAS,RUNNING_RPL,AUTHORIZED_RPL,UPDATED_RPL,AVAILABLE_RPL,UP_TO_DATE 2>/dev/null || kubectl get deploy app -n default -o jsonpath='{.status.replicas}
